-- PostgreSQL 15+; source systems separated by schema, platform read/write via adapters.
CREATE SCHEMA IF NOT EXISTS mock_erp;
CREATE SCHEMA IF NOT EXISTS mock_wms;
CREATE SCHEMA IF NOT EXISTS mock_mes;
CREATE SCHEMA IF NOT EXISTS platform;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE TABLE IF NOT EXISTS mock_erp.sales_orders (order_id text PRIMARY KEY, product_id text NOT NULL, quantity numeric(18,4) NOT NULL CHECK(quantity>0), due_date date NOT NULL, priority int NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('DRAFT','CONFIRMED','CANCELLED')), version bigint NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE IF NOT EXISTS mock_erp.bom_versions (bom_id text NOT NULL, version text NOT NULL, status text NOT NULL CHECK(status IN ('DRAFT','RELEASED')), effective_from date NOT NULL, effective_to date, PRIMARY KEY(bom_id,version), CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE IF NOT EXISTS mock_erp.bom_items (bom_id text NOT NULL, version text NOT NULL, line_id int NOT NULL, parent_id text NOT NULL, component_id text NOT NULL, qty_per numeric(18,4) NOT NULL CHECK(qty_per>0), PRIMARY KEY(bom_id,version,line_id), FOREIGN KEY(bom_id,version) REFERENCES mock_erp.bom_versions(bom_id,version));
CREATE TABLE IF NOT EXISTS mock_erp.materials (material_id text PRIMARY KEY, make_buy text NOT NULL CHECK(make_buy IN ('MAKE','BUY')), lead_days int NOT NULL CHECK(lead_days>=0), safety_stock numeric(18,4) NOT NULL DEFAULT 0 CHECK(safety_stock>=0), moq numeric(18,4) NOT NULL DEFAULT 0 CHECK(moq>=0), lot_multiple numeric(18,4) NOT NULL DEFAULT 1 CHECK(lot_multiple>0), uom text NOT NULL DEFAULT 'PCS');
CREATE TABLE IF NOT EXISTS mock_erp.supply_orders (supply_id text PRIMARY KEY, material_id text NOT NULL REFERENCES mock_erp.materials(material_id), open_qty numeric(18,4) NOT NULL CHECK(open_qty>=0), arrival_date date NOT NULL, status text NOT NULL DEFAULT 'CONFIRMED');
CREATE TABLE IF NOT EXISTS mock_erp.purchase_requests (pr_id text PRIMARY KEY, idempotency_key text UNIQUE NOT NULL, request_hash text NOT NULL, order_id text NOT NULL, status text NOT NULL DEFAULT 'CREATED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS mock_wms.inventory_balances (material_id text NOT NULL, warehouse_id text NOT NULL, lot_id text NOT NULL DEFAULT '', on_hand numeric(18,4) NOT NULL CHECK(on_hand>=0), reserved numeric(18,4) NOT NULL DEFAULT 0 CHECK(reserved>=0), blocked numeric(18,4) NOT NULL DEFAULT 0 CHECK(blocked>=0), snapshot_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1, PRIMARY KEY(material_id,warehouse_id,lot_id), CHECK(reserved+blocked<=on_hand));
CREATE TABLE IF NOT EXISTS mock_mes.production_orders (production_order_id text PRIMARY KEY, product_id text NOT NULL, planned_qty numeric(18,4) NOT NULL CHECK(planned_qty>0), status text NOT NULL);
CREATE TABLE IF NOT EXISTS platform.mapping_rules (mapping_id text NOT NULL, version int NOT NULL CHECK(version>0), source_system text NOT NULL, object_type text NOT NULL, mapping_json jsonb NOT NULL, PRIMARY KEY(mapping_id,version));
CREATE TABLE IF NOT EXISTS platform.requirement_runs (run_id text PRIMARY KEY, order_set_hash text NOT NULL, input_hash text NOT NULL, rule_version text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform.material_requirements (run_id text NOT NULL REFERENCES platform.requirement_runs(run_id), material_id text NOT NULL, need_date date NOT NULL, gross numeric(18,4) NOT NULL, net numeric(18,4) NOT NULL, planned numeric(18,4) NOT NULL, projected_balance numeric(18,4) NOT NULL, PRIMARY KEY(run_id,material_id,need_date));
CREATE TABLE IF NOT EXISTS platform.workflow_instances (instance_id text PRIMARY KEY, order_id text NOT NULL, state text NOT NULL, version bigint NOT NULL DEFAULT 1, trace_id text NOT NULL);
CREATE TABLE IF NOT EXISTS platform.approval_tasks (approval_id text PRIMARY KEY, instance_id text NOT NULL REFERENCES platform.workflow_instances(instance_id), state text NOT NULL, decision_version bigint NOT NULL DEFAULT 1, approver text);
CREATE TABLE IF NOT EXISTS audit.event_inbox (event_id text PRIMARY KEY, received_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS audit.event_outbox (id bigserial PRIMARY KEY, event_type text NOT NULL, payload jsonb NOT NULL, dispatched_at timestamptz);
CREATE TABLE IF NOT EXISTS audit.idempotency_records (idempotency_key text PRIMARY KEY, request_hash text NOT NULL, state text NOT NULL, external_id text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit.audit_logs (id bigserial PRIMARY KEY, trace_id text NOT NULL, actor text NOT NULL, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
